// OTHVM — Web search: تجهيز استعلام Bing (مجاني بدون مفاتيح)
const j = $input.first().json || {};
const q = String(j.query || '').trim();
const maxR = Math.min(10, Math.max(1, parseInt(j.maxResults, 10) || 5));
if (!q) return [{ json: { url: 'https://www.bing.com/search?q=test&form=QBLH', maxResults: maxR, query: '', bad: true, error: 'مطلوب نص البحث في الحقل query' } }];
return [{ json: { url: 'https://www.bing.com/search?q=' + encodeURIComponent(q) + '&form=QBLH', maxResults: maxR, query: q, bad: false } }];

// OTHVM — Web search: استخراج كوكيز جلسة Bing (تفادي بوابة البوتات)
const home = ($input.first() || {}).json || {};
const h = home.headers || {};
let sc = h['set-cookie'] || h['Set-Cookie'] || [];
if (!Array.isArray(sc)) sc = typeof sc === 'string' ? [sc] : [];
const cookie = sc.map((x) => String(x).split(';')[0].trim()).filter(Boolean).join('; ');
return [{ json: { cookie: cookie } }];

// OTHVM — Web search: تفكيك نتائج Bing إلى عناصر {title, url, snippet}
const prep = (($('web.search — Prepare').first() || {}).json) || {};
const first = (($input.first() || {}).json) || {};
if (prep.bad) return [{ json: { ok: false, error: prep.error || 'مدخل ناقص' } }];
function bodyOf(x) {
  if (typeof x === 'string') return x;
  if (x && typeof x === 'object') {
    if (x.error) return null;
    if (typeof x.data === 'string') return x.data;
    if (typeof x.body === 'string') return x.body;
  }
  return null;
}
const html = bodyOf(first);
if (html === null) {
  const e = first && first.error;
  const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? [e.message, e.description].filter(Boolean).join(' — ') : 'فشل الاتصال بمحرك البحث');
  return [{ json: { ok: false, error: String(msg).slice(0, 300) } }];
}
const ent = (s) => String(s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&hellip;/g, '…').replace(/&#(\d+);/g, (mm, d) => String.fromCharCode(Number(d)));
const strip = (s) => ent(String(s).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
function realUrl(href) {
  const h = String(href || '');
  const um = h.match(/u=a1([A-Za-z0-9_-]+)/);
  if (um) {
    try {
      let dec = Buffer.from(um[1], 'base64url').toString('utf8');
      try { dec = decodeURIComponent(dec); } catch (e) {}
      if (/^https?:\/\//i.test(dec)) return dec;
    } catch (e) {}
  }
  if (/^https?:\/\//i.test(h) && h.indexOf('bing.com') === -1) return h;
  return h;
}
const maxR = typeof prep.maxResults === 'number' ? prep.maxResults : 5;
const out = [];
const reLi = /<li class="b_algo[^"]*"[^>]*>/g;
const marks = [];
let m;
while ((m = reLi.exec(html)) !== null) marks.push(m.index + m[0].length);
for (let i = 0; i < marks.length && out.length < maxR; i++) {
  const start = marks[i];
  const end = i + 1 < marks.length ? marks[i + 1] : Math.min(html.length, start + 30000);
  const block = html.slice(start, end);
  const am = block.match(/<h2[^>]*>\s*<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
  if (!am) continue;
  const title = strip(am[2]).slice(0, 180);
  const url = realUrl(am[1]);
  if (!title || !url) continue;
  let snippet = '';
  const sm = block.match(/<p class="[^"]*b_lineclamp[^"]*"[^>]*>([\s\S]*?)<\/p>/) || block.match(/<p[^>]*>([\s\S]*?)<\/p>/);
  if (sm) snippet = strip(sm[1]).slice(0, 250);
  out.push({ json: { title: title, url: url, snippet: snippet } });
}
if (!out.length) {
  const capped = /b_results/.test(html) ? 'لا توجد نتائج للبحث ده — جرّب صياغة تانية' : 'رد غير متوقع من محرك البحث (حماية محتملة) — جرّب تاني';
  return [{ json: { ok: false, error: capped } }];
}
return out;

// OTHVM — Web news: تجهيز بحث أخبار Google News RSS (مجاني بدون مفاتيح)
const j = $input.first().json || {};
const q = String(j.query || '').trim();
const maxR = Math.min(15, Math.max(1, parseInt(j.maxResults, 10) || 8));
if (!q) return [{ json: { url: 'https://news.google.com/rss/search?q=test&hl=ar&gl=EG&ceid=EG:ar', maxResults: maxR, query: '', bad: true, error: 'مطلوب نص البحث في الحقل query' } }];
return [{ json: { url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=ar&gl=EG&ceid=EG:ar', maxResults: maxR, query: q, bad: false } }];

// OTHVM — Web news: تفكيك خلاصة Google News إلى عناصر {title, source, date, url}
const prep = (($('web.news — Prepare').first() || {}).json) || {};
const first = (($input.first() || {}).json) || {};
if (prep.bad) return [{ json: { ok: false, error: prep.error || 'مدخل ناقص' } }];
function bodyOf(x) {
  if (typeof x === 'string') return x;
  if (x && typeof x === 'object') {
    if (x.error) return null;
    if (typeof x.data === 'string') return x.data;
    if (typeof x.body === 'string') return x.body;
  }
  return null;
}
const xml = bodyOf(first);
if (xml === null) {
  const e = first && first.error;
  const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? [e.message, e.description].filter(Boolean).join(' — ') : 'فشل الاتصال بجوجل نيوز');
  return [{ json: { ok: false, error: String(msg).slice(0, 300) } }];
}
const ent = (s) => String(s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&#(\d+);/g, (mm, d) => String.fromCharCode(Number(d)));
const unwrap = (s) => String(s).replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
const items = [];
const reI = /<item>([\s\S]*?)<\/item>/g;
let m;
while ((m = reI.exec(xml)) !== null) {
  const it = m[1];
  const tt = it.match(/<title>([\s\S]*?)<\/title>/);
  const lk = it.match(/<link>([\s\S]*?)<\/link>/);
  const pd = it.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
  const sc = it.match(/<source[^>]*>([\s\S]*?)<\/source>/);
  const title = ent(unwrap(tt ? tt[1] : '')).replace(/\s+/g, ' ').trim();
  if (!title) continue;
  const item = { title: title.slice(0, 180) };
  if (lk) item.url = ent(unwrap(lk[1])).trim();
  if (sc) item.source = ent(unwrap(sc[1])).trim();
  if (pd) { const d = new Date(unwrap(pd[1]).trim()); if (!isNaN(d.getTime())) item.date = d.toISOString().slice(0, 16).replace('T', ' '); }
  items.push({ json: item });
}
if (!items.length) return [{ json: { ok: false, error: 'مفيش أخبار للبحث ده — جرّب صياغة تانية' } }];
return items.slice(0, typeof prep.maxResults === 'number' ? prep.maxResults : 8);

// OTHVM — Web fetch: تطبيع الرابط
const j = $input.first().json || {};
let u = String(j.url || '').trim();
if (!u) return [{ json: { url: 'https://example.com', bad: true, error: 'مطلوب رابط الصفحة في الحقل url' } }];
if (!/^https?:\/\//i.test(u)) {
  if (/^[\w.-]+\.[a-z]{2,}(\/|$)/i.test(u)) u = 'https://' + u;
  else return [{ json: { url: 'https://example.com', bad: true, error: 'الرابط غير صالح: ' + u.slice(0, 120) } }];
}
return [{ json: { url: u, bad: false } }];

// OTHVM — Web fetch: HTML → نص مقروء (حد 3500 حرف)
const prep = (($('web.fetch — Prepare').first() || {}).json) || {};
const first = (($input.first() || {}).json) || {};
if (prep.bad) return [{ json: { ok: false, error: prep.error || 'مدخل ناقص' } }];
function bodyOf(x) {
  if (typeof x === 'string') return x;
  if (x && typeof x === 'object') {
    if (x.error) return null;
    if (typeof x.data === 'string') return x.data;
    if (typeof x.body === 'string') return x.body;
  }
  return null;
}
const html = bodyOf(first);
if (html === null) {
  const e = first && first.error;
  const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? [e.message, e.description].filter(Boolean).join(' — ') : 'فشل فتح الصفحة');
  return [{ json: { ok: false, error: String(msg).slice(0, 300) } }];
}
const ent = (s) => String(s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&hellip;/g, '…').replace(/&#(\d+);/g, (mm, d) => String.fromCharCode(Number(d)));
const strip = (s) => ent(String(s).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const titleM = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ');
text = text.replace(/<\/(p|div|li|h[1-6]|tr|section|article)>/gi, '\n').replace(/<br\s*\/?>/gi, '\n');
text = text.replace(/<[^>]+>/g, ' ');
text = ent(text).replace(/[ \t\u00a0]+/g, ' ').replace(/\n\s*\n\s*\n+/g, '\n\n').replace(/^\s+|\s+$/g, '');
if (!text) return [{ json: { ok: false, error: 'الصفحة مفيهاش نص مقروء (يمكن ملف أو محتوى جافاسكريبت)' } }];
const cut = text.slice(0, 3500);
return [{ json: { ok: true, url: prep.url, title: strip(titleM ? titleM[1] : ''), text: cut, truncated: text.length > 3500 } }];

// OTHVM — Web Tool output normalizer: JSON مضغوط + حدود حجم (نصوص 3500، إجمالي 12KB)
const out = [];
let total = 0;
for (const item of $input.all().slice(0, 25)) {
  if (item.error) { const e = item.error; const msg = [e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error'; out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const j = item.json || {};
  if (j.ok === false || (Object.keys(j).length === 1 && 'error' in j)) { const e = j.error; const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? ([e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error') : String(e || 'unknown error')); out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const o = {};
  for (const [k, v] of Object.entries(j)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string') o[k] = v.length > 3500 ? v.slice(0, 3500) + '…' : v;
    else if (typeof v === 'object') { const s = JSON.stringify(v); o[k] = s.length > 500 ? s.slice(0, 500) + '…' : v; }
    else o[k] = v;
  }
  if (!Object.keys(o).length) continue;
  const s = JSON.stringify(o);
  if (total + s.length > 12000) break;
  total += s.length;
  out.push({ json: o });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

// OTHVM — expand the generic params object into the flat fields the workflow expects.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = Object.assign({}, p);
for (const k of ['operation', 'action', 'category']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') out[k] = j[k];
}
return [{ json: out }];
